#!/bin/bash
# Demo-scenario check (user request 2026-11-10 #3): an ACTIVE manual_review_required policy generated by v7
# (GET /orders/{orderId}) is edited through the admin API to owner_match (rollback -> PUT -> approve) and the
# same BOLA request that passed under manual must then be blocked. Runs on a COPY of the v7 policy store so the
# generated set in ./policies stays as produced. No runtime code is modified.
source /c/BLADE/verification/demo_v7_runtime/env.sh
WORK=/c/BLADE/verification/demo_v7_runtime/scenario_run
rm -rf "$WORK"; mkdir -p "$WORK"; cp /c/BLADE/verification/demo_v7_runtime/blade.db "$WORK/"; cp -r /c/BLADE/verification/demo_v7_runtime/policies "$WORK/policies"
cp /c/BLADE/verification/demo_v7_runtime/demo.db "$WORK/demo.db"
cd "$WORK"
export BLADE_PROXY_HOST=127.0.0.1
LOG=/c/BLADE/verification/demo_v7_runtime/scenario_manual_to_owner.log
: > "$LOG"
log() { echo "$(date -u +%FT%TZ) $*" | tee -a "$LOG"; }
python -m uvicorn demo_backend.main:app --host 127.0.0.1 --port 9000 > backend.log 2>&1 & P1=$!
python -m uvicorn admin_api.main:app --host 127.0.0.1 --port 8100 > admin.log 2>&1 & P2=$!
for i in $(seq 1 60); do curl -s --max-time 2 http://127.0.0.1:8100/policies >/dev/null && curl -s --max-time 2 http://127.0.0.1:9000/public/health >/dev/null && break; sleep 1; done
python -m proxy.server > proxy.log 2>&1 & P3=$!
for i in $(seq 1 60); do curl -s --max-time 2 -o /dev/null http://127.0.0.1:8080/public/health && break; sleep 1; done
log "stack up backend=$P1 admin=$P2 proxy=$P3"
python -X utf8 - <<'PY'
import jwt, os, time, json
s = os.environ['BLADE_JWT_SECRET']
def tok(user, roles, tenant):
    return jwt.encode(dict(sub=user, roles=roles, tenant_id=tenant, membership='basic', exp=int(time.time()) + 3600), s, algorithm='HS256')
json.dump({'user_99': tok('user_99', ['user'], 'org_2'), 'user_77': tok('user_77', ['user'], 'org_1')}, open('tokens.json', 'w'))
PY
T99=$(python -c "import json;print(json.load(open('tokens.json'))['user_99'])"); T77=$(python -c "import json;print(json.load(open('tokens.json'))['user_77'])")
req() { curl -s -o /dev/null -w "%{http_code}" -H "Authorization: Bearer $1" http://127.0.0.1:8080/orders/1042; }
log "A) policy before: $(curl -s http://127.0.0.1:8100/policies/pol_orders_get_by_orderId | python -X utf8 -c 'import json,sys;p=json.load(sys.stdin);print(p["label"],p["status"],p["mode"],p["version"],p["source"])')"
log "A) GET /orders/1042 as user_99 (BOLA, manual policy) -> $(req $T99) ; as user_77 (owner) -> $(req $T77)"
log "B) rollback ACTIVE->PENDING: $(curl -s -o /dev/null -w '%{http_code}' -X POST http://127.0.0.1:8100/policies/pol_orders_get_by_orderId/rollback)"
curl -s http://127.0.0.1:8100/policies/pol_orders_get_by_orderId > before.json
python -X utf8 - <<'PY'
import json
p = json.load(open('before.json', encoding='utf-8'))
body = {k: p[k] for k in ('id', 'endpoint', 'label', 'params', 'confidence', 'evidence', 'created_at', 'mode', 'version', 'source')}
body['label'] = 'owner_match'
body['params'] = {**body['params'], 'object_param': 'orderId', 'owner_lookup': {'table': 'orders', 'id_col': 'id', 'owner_col': 'user_id', 'tenant_col': None}}
body['evidence'] = body['evidence'] + ' | 사람 수정(데모 시나리오): manual -> owner_match, owner_lookup orders.id owner=user_id'
body['source'] = 'manual'
json.dump(body, open('put_body.json', 'w', encoding='utf-8'), ensure_ascii=False)
PY
log "B) PUT label owner_match: $(curl -s -o put_resp.json -w '%{http_code}' -X PUT -H 'Content-Type: application/json' --data-binary @put_body.json http://127.0.0.1:8100/policies/pol_orders_get_by_orderId) $(python -X utf8 -c 'import json;p=json.load(open("put_resp.json",encoding="utf-8"));print(p.get("label"),p.get("status"),p.get("version"),p.get("source"),p.get("detail"))')"
log "B) approve PENDING->ACTIVE: $(curl -s -o appr.json -w '%{http_code}' -X POST http://127.0.0.1:8100/policies/pol_orders_get_by_orderId/approve) $(python -X utf8 -c 'import json;p=json.load(open("appr.json",encoding="utf-8"));print(p.get("label"),p.get("status"),p.get("mode"),p.get("detail"))')"
sleep 8
log "C) after poll: GET /orders/1042 as user_99 (BOLA) -> $(req $T99) ; as user_77 (owner) -> $(req $T77) ; no token -> $(curl -s -o /dev/null -w '%{http_code}' http://127.0.0.1:8080/orders/1042)"
log "C) detections (last 3): $(curl -s 'http://127.0.0.1:8100/detections' | python -X utf8 -c 'import json,sys;d=json.load(sys.stdin);print(len(d), [ (x.get("verdict"), x.get("reason") or x.get("rule")) for x in d[-3:]])' 2>/dev/null)"
kill $P3 $P2 $P1 2>/dev/null; sleep 1
log "stack stopped; original ./policies untouched: $(cd /c/BLADE/verification/demo_v7_runtime && python -X utf8 -c 'import yaml;print(yaml.safe_load(open("policies/pol_orders_get_by_orderId.yaml",encoding="utf-8"))["label"])')"
